import React, { useEffect, useRef } from "react";
import { getReducedMotionPreference, subscribePrefersReducedMotion } from "./motion";

type Particle = { x: number; y: number; vx: number; vy: number };

/**
 * Fullscreen canvas: neon particles + mesh links (default) or calmer drift (reduced motion).
 */
const LiveBackground: React.FC = () => {
  const canvasRef = useRef<HTMLCanvasElement | null>(null);
  const rafRef = useRef<number | null>(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext("2d", { alpha: true });
    if (!ctx) return;

    const dpr = Math.min(window.devicePixelRatio || 1, 2);
    let w = window.innerWidth;
    let h = window.innerHeight;
    let particles: Particle[] = [];
    let reducedMotion = getReducedMotionPreference();

    const linkDist = 118;
    const linkDistSq = linkDist * linkDist;
    const cellSize = linkDist;

    const fullSpeed = 0.42;
    const reducedSpeed = 0.07;

    function currentSpeed(): number {
      return reducedMotion ? reducedSpeed : fullSpeed;
    }

    function desiredParticleCount(): number {
      const area = w * h;

      if (reducedMotion) {
        let n = Math.floor(area / 24_000);
        return Math.min(28, Math.max(16, n));
      }

      let n = Math.floor(area / 10_500);
      n = Math.min(108, Math.max(34, n));

      const nav = navigator as Navigator & {
        connection?: { saveData?: boolean; effectiveType?: string };
      };
      const conn = nav.connection;
      if (conn?.saveData) n = Math.min(n, 40);
      if (conn?.effectiveType && /2g|slow-2g/.test(conn.effectiveType)) n = Math.min(n, 38);

      const cores = nav.hardwareConcurrency;
      if (typeof cores === "number" && cores <= 4) n = Math.min(n, Math.round(n * 0.82));

      return Math.max(28, n);
    }

    function resizeCanvas() {
      canvas.width = Math.max(1, Math.floor(w * dpr));
      canvas.height = Math.max(1, Math.floor(h * dpr));
      canvas.style.width = `${w}px`;
      canvas.style.height = `${h}px`;
      ctx.setTransform(1, 0, 0, 1, 0, 0);
      ctx.scale(dpr, dpr);
    }

    function initParticles() {
      const n = desiredParticleCount();
      const spd = currentSpeed();
      particles = [];
      for (let i = 0; i < n; i++) {
        particles.push({
          x: Math.random() * w,
          y: Math.random() * h,
          vx: (Math.random() - 0.5) * spd,
          vy: (Math.random() - 0.5) * spd,
        });
      }
    }

    resizeCanvas();
    initParticles();

    function drawParticleNode(x: number, y: number) {
      ctx.beginPath();
      ctx.arc(x, y, 5.2, 0, Math.PI * 2);
      ctx.fillStyle = "rgba(0, 229, 255, 0.1)";
      ctx.fill();

      ctx.beginPath();
      ctx.arc(x, y, 3.2, 0, Math.PI * 2);
      ctx.fillStyle = "rgba(0, 229, 255, 0.22)";
      ctx.fill();

      ctx.beginPath();
      ctx.arc(x, y, 1.65, 0, Math.PI * 2);
      ctx.fillStyle = "#b8fcff";
      ctx.fill();

      ctx.beginPath();
      ctx.arc(x, y, 0.9, 0, Math.PI * 2);
      ctx.fillStyle = "#ffffff";
      ctx.fill();
    }

    let frameTick = 0;

    function draw() {
      frameTick += 1;
      if (reducedMotion && frameTick % 2 !== 0) {
        rafRef.current = requestAnimationFrame(draw);
        return;
      }

      if (reducedMotion) {
        ctx.fillStyle = "#080b12";
        ctx.fillRect(0, 0, w, h);
      } else {
        ctx.fillStyle = "rgba(8, 11, 18, 0.36)";
        ctx.fillRect(0, 0, w, h);
      }

      for (let i = 0; i < particles.length; i++) {
        const p = particles[i];
        p.x += p.vx;
        p.y += p.vy;
        if (p.x < 0 || p.x > w) p.vx *= -1;
        if (p.y < 0 || p.y > h) p.vy *= -1;
        p.x = Math.min(w, Math.max(0, p.x));
        p.y = Math.min(h, Math.max(0, p.y));
      }

      if (!reducedMotion) {
        const buckets = new Map<string, number[]>();
        for (let i = 0; i < particles.length; i++) {
          const p = particles[i];
          const key = `${Math.floor(p.x / cellSize)},${Math.floor(p.y / cellSize)}`;
          let bucket = buckets.get(key);
          if (!bucket) {
            bucket = [];
            buckets.set(key, bucket);
          }
          bucket.push(i);
        }

        ctx.lineWidth = 1;
        const invW = w > 0 ? 1 / w : 0;
        const invH = h > 0 ? 1 / h : 0;

        for (let i = 0; i < particles.length; i++) {
          const a = particles[i];
          const cx = Math.floor(a.x / cellSize);
          const cy = Math.floor(a.y / cellSize);

          for (let ox = -1; ox <= 1; ox++) {
            for (let oy = -1; oy <= 1; oy++) {
              const list = buckets.get(`${cx + ox},${cy + oy}`);
              if (!list) continue;
              for (let k = 0; k < list.length; k++) {
                const j = list[k];
                if (j <= i) continue;
                const b = particles[j];
                const dx = a.x - b.x;
                const dy = a.y - b.y;
                const d2 = dx * dx + dy * dy;
                if (d2 >= linkDistSq) continue;
                const d = Math.sqrt(d2);
                const fade = 1 - d / linkDist;
                const alpha = 0.4 * fade;
                const mix = Math.min(
                  1,
                  Math.max(0, ((a.x + b.x) * 0.5 * invW + (a.y + b.y) * 0.5 * invH) * 0.5)
                );
                const r = mix * 124;
                const g = (1 - mix) * 229 + mix * 77;
                const bch = 255;
                ctx.strokeStyle = `rgba(${r | 0},${g | 0},${bch},${alpha})`;
                ctx.beginPath();
                ctx.moveTo(a.x, a.y);
                ctx.lineTo(b.x, b.y);
                ctx.stroke();
              }
            }
          }
        }
      }

      for (let i = 0; i < particles.length; i++) {
        drawParticleNode(particles[i].x, particles[i].y);
      }

      rafRef.current = requestAnimationFrame(draw);
    }

    let resizeDebounce: number | null = null;
    const onResize = () => {
      if (resizeDebounce != null) window.clearTimeout(resizeDebounce);
      resizeDebounce = window.setTimeout(() => {
        resizeDebounce = null;
        w = window.innerWidth;
        h = window.innerHeight;
        resizeCanvas();
        initParticles();
      }, 120);
    };

    const unsubMotion = subscribePrefersReducedMotion(next => {
      reducedMotion = next;
      frameTick = 0;
      initParticles();
    });

    window.addEventListener("resize", onResize);
    rafRef.current = requestAnimationFrame(draw);

    return () => {
      unsubMotion();
      window.removeEventListener("resize", onResize);
      if (resizeDebounce != null) window.clearTimeout(resizeDebounce);
      if (rafRef.current != null) cancelAnimationFrame(rafRef.current);
    };
  }, []);

  return <canvas ref={canvasRef} className="bg-canvas" aria-hidden="true" />;
};

export default LiveBackground;
